"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["47122"],{24145(t){t.exports=JSON.parse('{"id":"FIN-420","slug":"discount-factor","term":"Discount Factor","also_known_as":["Present Value Factor"],"difficulty":"Intermediate","definition":"A discount factor is the number that a future cash flow is multiplied by to convert it into its present value. It is always less than 1 for positive discount rates and future dates.","explanation":["The discount factor depends on the discount rate and the discount period. It is calculated as 1 divided by one plus the discount rate, raised to the power of the number of periods.","For example, at a discount rate of 8%, the discount factor for a cash flow received in three years is 1 divided by 1.08 to the power of 3, which is about 0.794. A cash flow of 10,000 received in three years is therefore worth about 7,938 today.","Discount factors get smaller as the discount rate rises or the cash flow moves further into the future. At 8%, the factor for one year is about 0.926, for ten years about 0.463 and for twenty years about 0.215.","Using discount factors makes valuation calculations easier to follow and check. In a spreadsheet model, each year\'s cash flow is multiplied by its discount factor, and the results are added up to give the total present value."],"note":"A present value factor means the same as a discount factor. Both describe the multiplier that converts a future amount into today\'s value.","total":1500,"prev":{"slug":"disclaimer-of-opinion","term":"Disclaimer of Opinion"},"next":{"slug":"discount-for-lack-of-control","term":"Discount for Lack of Control"}}')}}]);